insert into senses (id, lemma, pos, gloss, examples, date_label, date_earliest, obsolete_year, obsolete_label, shift, source, source_type) values
  ('cloud.n.01', 'cloud', 'noun', 'a mass of rock; a hill', '[]', 'Old English', 900, 1400, 'by 15th c.', 'root', 'Oxford English Dictionary, cloud n., sense 1', 'dictionary'),
  ('cloud.n.02', 'cloud', 'noun', 'a visible mass of water or ice particles floating in the atmosphere', '["the clouds parted and the sun came out"]', 'c. 1300', 1300, null, null, 'metaphor', 'Middle English Dictionary, cloud n.', 'dictionary'),
  ('cloud.n.03', 'cloud', 'noun', 'a large number of things moving together through the air', '["a cloud of locusts"]', 'c. 1400', 1400, null, null, 'broadening', 'Middle English Dictionary, cloud n.', 'dictionary'),
  ('cloud.n.04', 'cloud', 'noun', 'a state of gloom, trouble or suspicion', '["he left the company under a cloud"]', '16th c.', 1500, null, null, 'metaphor', 'Oxford English Dictionary', 'dictionary'),
  ('cloud.v.01', 'cloud', 'verb', 'to cover or become covered with clouds', '["the sky clouded over by noon"]', 'late 16th c.', 1580, null, null, 'other', 'Oxford English Dictionary', 'dictionary'),
  ('cloud.v.02', 'cloud', 'verb', 'to make unclear, or less able to think clearly', '["anger clouded his judgement"]', 'c. 1600', 1600, null, null, 'metaphor', 'Oxford English Dictionary', 'dictionary'),
  ('cloud.n.05', 'cloud', 'noun', 'a cloud-shaped symbol standing for an unspecified network in a diagram', '[]', '1970s', 1970, null, null, 'metonymy', 'Telecommunications engineering diagrams', 'citation'),
  ('cloud.n.06', 'cloud', 'noun', 'remote servers reached over the internet, used to store and process data', '["back up your photos to the cloud"]', '1990s', 1990, null, null, 'metaphor', 'Computing trade press', 'corpus'),
  ('mouse.n.01', 'mouse', 'noun', 'a small rodent with a pointed snout, small ears and a long tail', '["a mouse ran under the stove"]', 'Old English', 800, null, null, 'root', 'Oxford English Dictionary', 'dictionary'),
  ('mouse.n.02', 'mouse', 'noun', 'a quiet or timid person', '["she was too much of a mouse to complain"]', '16th c.', 1520, null, null, 'metaphor', 'Oxford English Dictionary', 'dictionary'),
  ('mouse.n.03', 'mouse', 'noun', 'a swelling or black eye caused by a blow', '[]', '1840s', 1842, 1950, 'mid-20th c.', 'metaphor', 'Old Bailey Proceedings', 'corpus'),
  ('mouse.n.04', 'mouse', 'noun', 'a hand-operated device that moves a pointer on a computer screen', '["click the left mouse button"]', '1965', 1965, null, null, 'metaphor', 'Research report on display control, 1965', 'citation'),
  ('mouse.v.01', 'mouse', 'verb', 'to move a pointer or select items using a mouse', '["mouse over the icon to see its name"]', '1980s', 1984, null, null, 'other', 'Computing magazines', 'corpus'),
  ('web.n.01', 'web', 'noun', 'a piece of cloth woven on a loom', '[]', 'Old English', 850, null, null, 'root', 'Oxford English Dictionary', 'dictionary'),
  ('web.n.02', 'web', 'noun', 'a net of fine threads spun by a spider', '["a spider was mending its web"]', '13th c.', 1200, null, null, 'metaphor', 'Oxford English Dictionary', 'dictionary'),
  ('web.n.03', 'web', 'noun', 'an intricate network suggesting something woven', '["a web of lies"]', 'late 16th c.', 1580, null, null, 'metaphor', 'Oxford English Dictionary', 'dictionary'),
  ('web.n.04', 'web', 'noun', 'the system of linked documents on the internet', '["she found the recipe on the web"]', '1990', 1990, null, null, 'metaphor', 'Project proposal, 1990', 'citation'),
  ('troll.v.01', 'troll', 'verb', 'to fish by trailing a baited line behind a moving boat', '[]', '17th c.', 1606, null, null, 'root', 'Oxford English Dictionary', 'dictionary'),
  ('troll.n.01', 'troll', 'noun', 'a giant or dwarf of Scandinavian folklore living in caves or hills', '[]', '1840s', 1840, null, null, 'root', 'Oxford English Dictionary', 'dictionary'),
  ('troll.v.02', 'troll', 'verb', 'to post deliberately provocative messages online', '["he was trolling the forum again"]', '1992', 1992, null, null, 'metaphor', 'Usenet archive', 'corpus'),
  ('troll.n.02', 'troll', 'noun', 'a person who posts provocative messages online to upset others', '["don’t feed the trolls"]', '1990s', 1993, null, null, 'metonymy', 'Usenet archive', 'corpus'),
  ('virus.n.01', 'virus', 'noun', 'venom, as of a snake; a poisonous substance', '[]', 'late 14th c.', 1390, 1800, 'by 19th c.', 'root', 'Middle English Dictionary, virus n.', 'dictionary'),
  ('virus.n.02', 'virus', 'noun', 'an infective agent that multiplies only inside the living cells of an organism', '[]', '1890s', 1892, null, null, 'narrowing', 'Medical journals', 'corpus'),
  ('virus.n.03', 'virus', 'noun', 'a program that copies itself into other programs and spreads between computers', '["the virus deleted every file"]', '1970s', 1972, null, null, 'metaphor', 'Oxford English Dictionary', 'dictionary'),
  ('viral.adj.01', 'viral', 'adjective', 'of, relating to or caused by a virus', '["a viral infection"]', '1940s', 1944, null, null, 'other', 'Oxford English Dictionary', 'dictionary'),
  ('viral.adj.02', 'viral', 'adjective', 'spreading quickly from person to person, especially online', '["the video went viral"]', '1980s', 1989, null, null, 'metaphor', 'Marketing press', 'corpus'),
  ('nice.adj.01', 'nice', 'adjective', 'foolish or ignorant', '[]', 'c. 1300', 1300, 1600, 'by 17th c.', 'root', 'Middle English Dictionary, nice adj.', 'dictionary'),
  ('nice.adj.02', 'nice', 'adjective', 'requiring great precision or care; subtle', '["a nice distinction"]', '16th c.', 1520, null, null, 'other', 'Oxford English Dictionary', 'dictionary'),
  ('nice.adj.03', 'nice', 'adjective', 'pleasant or agreeable', '["we had a nice time"]', 'mid-18th c.', 1760, null, null, 'amelioration', 'Oxford English Dictionary', 'dictionary');
