insert into sources (id, kind, title, author, publisher, published_label, published_year, url, identifier, accessed_on) values
  ('32d809e0-2530-5a2f-92e9-a9f6fe263bd6', 'book', 'The Holy Bible (King James Version)', null, 'Robert Barker', '1611', 1611, null, null, null),
  ('17eebd44-6279-5fce-8c6a-e824d09aa7b7', 'book', 'Hamlet, Prince of Denmark', 'William Shakespeare', null, 'c. 1600', 1600, null, null, null),
  ('2c7ccc9d-eba0-558c-a7ea-ffd7f73e83db', 'book', 'Richard III', 'William Shakespeare', null, '1597', 1597, null, null, null),
  ('93bff764-b98a-5f70-8560-8368c4087e08', 'book', 'Poems, in Two Volumes', 'William Wordsworth', 'Longman', '1807', 1807, null, null, null),
  ('c7f07d5d-083c-55c6-b5ab-003a7848ab7b', 'book', 'Marmion: A Tale of Flodden Field', 'Walter Scott', 'Archibald Constable', '1808', 1808, null, null, null),
  ('b6780604-043e-56cf-94eb-84f15f5aba0e', 'book', 'On the Origin of Species', 'Charles Darwin', 'John Murray', '1859', 1859, null, null, null),
  ('5934ce2d-095e-5822-9b49-e158f36785bd', 'book', 'Northanger Abbey', 'Jane Austen', 'John Murray', '1817', 1817, null, null, null),
  ('220ef869-157b-5f6d-bea9-9b68cd6a7dc0', 'website', 'WorldWideWeb: Proposal for a HyperText Project', 'Tim Berners-Lee and Robert Cailliau', 'CERN', '12 November 1990', 1990, 'https://www.w3.org/Proposal.html', null, '2026-10-22'),
  ('c2dbef12-2580-59fa-a227-94b3e97cb27f', 'article', 'Computer Viruses: Theory and Experiments', 'Fred Cohen', 'Proceedings of the 7th DoD/NBS Computer Security Conference', '1984', 1984, null, null, null),
  ('5e461e13-d171-5df2-8f00-10582d6570ce', 'other', 'Conversation with Eric Schmidt, Search Engine Strategies Conference', 'Eric Schmidt', 'Search Engine Strategies', '9 August 2006', 2006, null, null, null);
insert into attestations (id, sense_id, source_id, quote, year, date_label, locator, validation, validated_at) values
  ('fec6ef83-69c7-50e4-879f-e77d642d0df9', 'cloud.n.02', '32d809e0-2530-5a2f-92e9-a9f6fe263bd6', 'I doe set my bow in the cloud, and it shall be for a token of a couenant betweene me and the earth.', 1611, null, 'Genesis 9:13', 'editorial', null),
  ('462d2a30-0f6d-521b-8f4d-94d5d86ffcd2', 'cloud.n.02', '32d809e0-2530-5a2f-92e9-a9f6fe263bd6', 'And the LORD went before them by day in a pillar of a cloud, to lead them the way.', 1611, null, 'Exodus 13:21', 'editorial', null),
  ('51f881e1-6520-5cbc-a3c7-892f9ca17803', 'cloud.n.02', '17eebd44-6279-5fce-8c6a-e824d09aa7b7', 'Do you see yonder cloud that''s almost in shape of a camel?', 1600, 'c. 1600', 'Act 3, scene 2', 'editorial', null),
  ('62895368-7120-5605-8c5a-34151e512369', 'cloud.n.02', '93bff764-b98a-5f70-8560-8368c4087e08', 'I wandered lonely as a cloud / That floats on high o''er vales and hills', 1807, null, null, 'editorial', null),
  ('6cd3e9dc-be09-5456-b74c-d2b5cab744b5', 'cloud.n.04', '2c7ccc9d-eba0-558c-a7ea-ffd7f73e83db', 'And all the clouds that lour''d upon our house / In the deep bosom of the ocean buried.', 1597, null, 'Act 1, scene 1', 'editorial', null),
  ('ae77e668-a332-597f-8b77-bbbb8ae40a65', 'cloud.n.06', '5e461e13-d171-5df2-8f00-10582d6570ce', 'It starts with the premise that the data services and architecture should be on servers. We call it cloud computing; they should be in a "cloud" somewhere.', 2006, '9 August 2006', null, 'automatic', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('e2323a2e-5f05-50f1-94e8-32f56b098480', 'web.n.03', 'c7f07d5d-083c-55c6-b5ab-003a7848ab7b', 'O, what a tangled web we weave, / When first we practise to deceive!', 1808, null, 'Canto 6, stanza 17', 'editorial', null),
  ('af5e9921-048c-5af6-af0b-da6173c3b5ec', 'web.n.03', 'b6780604-043e-56cf-94eb-84f15f5aba0e', 'I am tempted to give one more instance showing how plants and animals, most remote in the scale of nature, are bound together by a web of complex relations.', 1859, null, 'ch. 3', 'editorial', null),
  ('9955e3a5-645b-5136-89bd-84cfd56d490d', 'web.n.04', '220ef869-157b-5f6d-bea9-9b68cd6a7dc0', 'HyperText is a way to link and access information of various kinds as a web of nodes in which the user can browse at will.', 1990, 'November 1990', null, 'editorial', null),
  ('b59c6376-9516-5fd9-a7e3-17b5bb1a9218', 'virus.n.03', 'c2dbef12-2580-59fa-a227-94b3e97cb27f', 'We define a computer ''virus'' as a program that can ''infect'' other programs by modifying them to include a possibly evolved copy of itself.', 1984, null, null, 'editorial', null),
  ('c420f818-882f-5930-80b6-1fbcaf6d1a7d', 'nice.adj.03', '5934ce2d-095e-5822-9b49-e158f36785bd', 'This is a very nice day, and we are taking a very nice walk; and you are two very nice young ladies. Oh! It is a very nice word indeed! It does for everything.', 1817, null, 'ch. 14', 'manual', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
